window.PHONETICS=[{"c":"Гласные","l":"ou","ipa":"[u]","ru":"«у»","d":"Губы вытянуты вперёд, звук короткий и чистый.","ex":[{"w":"v[ou]s","ipa":"[vu]","ru":"вы"},{"w":"r[ou]ge","ipa":"[ʁuʒ]","ru":"красный"},{"w":"j[ou]r","ipa":"[ʒuʁ]","ru":"день"},{"w":"beauc[ou]p","ipa":"[bo.ku]","ru":"много"}]},{"c":"Гласные","l":"u","ipa":"[y]","ru":"между «и» и «у»","d":"Скажите «и», не двигая языком вытяните губы трубочкой. В русском такого звука нет.","ex":[{"w":"t[u]","ipa":"[ty]","ru":"ты"},{"w":"r[u]e","ipa":"[ʁy]","ru":"улица"},{"w":"l[u]ne","ipa":"[lyn]","ru":"луна"},{"w":"s[u]r","ipa":"[syʁ]","ru":"на"}]},{"c":"Гласные","l":"oi","ipa":"[wa]","ru":"«уа»","d":"Всегда читается как короткое «уа».","ex":[{"w":"m[oi]","ipa":"[mwa]","ru":"я"},{"w":"tr[oi]s","ipa":"[tʁwa]","ru":"три"},{"w":"b[oi]re","ipa":"[bwaʁ]","ru":"пить"},{"w":"v[oi]ture","ipa":"[vwa.tyʁ]","ru":"машина"}]},{"c":"Гласные","l":"au, eau","ipa":"[o]","ru":"«о»","d":"Закрытое «о», губы округлены. Никогда не «ау».","ex":[{"w":"b[eau]","ipa":"[bo]","ru":"красивый"},{"w":"ch[au]d","ipa":"[ʃo]","ru":"горячий"},{"w":"[eau]","ipa":"[o]","ru":"вода"},{"w":"[au]ssi","ipa":"[o.si]","ru":"тоже"}]},{"c":"Гласные","l":"ai, ei","ipa":"[ɛ]","ru":"«э»","d":"Открытое «э», как в слове «это».","ex":[{"w":"l[ai]t","ipa":"[lɛ]","ru":"молоко"},{"w":"m[ai]son","ipa":"[mɛ.zɔ̃]","ru":"дом"},{"w":"n[ei]ge","ipa":"[nɛʒ]","ru":"снег"},{"w":"tr[ai]n","ipa":"[tʁɛ̃]","ru":"поезд (здесь носовой!)"}]},{"c":"Гласные","l":"eu, œu","ipa":"[ø] / [œ]","ru":"между «о» и «э»","d":"Как немецкое ö: губы округлены, язык как для «э».","ex":[{"w":"p[eu]","ipa":"[pø]","ru":"мало"},{"w":"bl[eu]","ipa":"[blø]","ru":"синий"},{"w":"s[œu]r","ipa":"[sœʁ]","ru":"сестра"},{"w":"h[eu]re","ipa":"[œʁ]","ru":"час"}]},{"c":"Гласные","l":"é","ipa":"[e]","ru":"«е» без «й»","d":"Закрытый узкий звук, уголки губ растянуты.","ex":[{"w":"caf[é]","ipa":"[ka.fe]","ru":"кофе"},{"w":"[é]t[é]","ipa":"[e.te]","ru":"лето"},{"w":"b[é]b[é]","ipa":"[be.be]","ru":"младенец"}]},{"c":"Гласные","l":"è, ê","ipa":"[ɛ]","ru":"«э»","d":"Открытый звук, рот шире, чем для é.","ex":[{"w":"m[è]re","ipa":"[mɛʁ]","ru":"мать"},{"w":"f[ê]te","ipa":"[fɛt]","ru":"праздник"},{"w":"t[ê]te","ipa":"[tɛt]","ru":"голова"}]},{"c":"Гласные","l":"e (без знака)","ipa":"[ə] или не читается","ru":"беглое «ё/э»","d":"В середине слова часто проглатывается, на конце слова не читается.","ex":[{"w":"l[e]","ipa":"[lə]","ru":"(артикль)"},{"w":"p[e]tit","ipa":"[pti]","ru":"маленький"},{"w":"tabl[e]","ipa":"[tabl]","ru":"стол"}]},{"c":"Гласные","l":"y","ipa":"[i]","ru":"«и»","d":"Между гласными читается как «й».","ex":[{"w":"st[y]lo","ipa":"[sti.lo]","ru":"ручка"},{"w":"[y]","ipa":"[i]","ru":"там"},{"w":"vo[y]age","ipa":"[vwa.jaʒ]","ru":"путешествие"}]},{"c":"Носовые","l":"an, am, en, em","ipa":"[ɑ̃]","ru":"«а» в нос","d":"Звук «а» произносится через нос, «н» не произносится.","ex":[{"w":"[an]","ipa":"[ɑ̃]","ru":"год"},{"w":"ch[am]bre","ipa":"[ʃɑ̃bʁ]","ru":"комната"},{"w":"[en]fant","ipa":"[ɑ̃.fɑ̃]","ru":"ребёнок"},{"w":"t[em]ps","ipa":"[tɑ̃]","ru":"время"}]},{"c":"Носовые","l":"in, im, ain, ein","ipa":"[ɛ̃]","ru":"«э» в нос","d":"Открытое «э» через нос.","ex":[{"w":"v[in]","ipa":"[vɛ̃]","ru":"вино"},{"w":"p[ain]","ipa":"[pɛ̃]","ru":"хлеб"},{"w":"pl[ein]","ipa":"[plɛ̃]","ru":"полный"},{"w":"[im]portant","ipa":"[ɛ̃.pɔʁ.tɑ̃]","ru":"важный"}]},{"c":"Носовые","l":"on, om","ipa":"[ɔ̃]","ru":"«о» в нос","d":"Округлённое «о» через нос.","ex":[{"w":"n[on]","ipa":"[nɔ̃]","ru":"нет"},{"w":"b[on]","ipa":"[bɔ̃]","ru":"хороший"},{"w":"n[om]","ipa":"[nɔ̃]","ru":"имя"},{"w":"m[on]tagne","ipa":"[mɔ̃.taɲ]","ru":"гора"}]},{"c":"Носовые","l":"un, um","ipa":"[œ̃]","ru":"«э» в нос (часто как in)","d":"Многие французы произносят его как [ɛ̃].","ex":[{"w":"[un]","ipa":"[œ̃]","ru":"один"},{"w":"br[un]","ipa":"[bʁœ̃]","ru":"коричневый"},{"w":"parf[um]","ipa":"[paʁ.fœ̃]","ru":"духи"}]},{"c":"Носовые","l":"Когда НЕ носовой","ipa":"—","ru":"n читается","d":"Если после n/m идёт гласная или вторая n/m, звук не носовой.","ex":[{"w":"bo[nn]e","ipa":"[bɔn]","ru":"хорошая"},{"w":"a[n]imal","ipa":"[a.ni.mal]","ru":"животное"},{"w":"fe[mm]e","ipa":"[fam]","ru":"женщина"}]},{"c":"Согласные","l":"ch","ipa":"[ʃ]","ru":"«ш»","d":"Мягкое «ш».","ex":[{"w":"[ch]at","ipa":"[ʃa]","ru":"кошка"},{"w":"[ch]ercher","ipa":"[ʃɛʁ.ʃe]","ru":"искать"},{"w":"bou[ch]e","ipa":"[buʃ]","ru":"рот"}]},{"c":"Согласные","l":"gn","ipa":"[ɲ]","ru":"«нь»","d":"Как «нь» в слове «коньяк».","ex":[{"w":"monta[gn]e","ipa":"[mɔ̃.taɲ]","ru":"гора"},{"w":"campa[gn]e","ipa":"[kɑ̃.paɲ]","ru":"деревня"},{"w":"si[gn]e","ipa":"[siɲ]","ru":"знак"}]},{"c":"Согласные","l":"ill","ipa":"[ij]","ru":"«ий»","d":"После гласной — только «й».","ex":[{"w":"f[ill]e","ipa":"[fij]","ru":"девочка"},{"w":"trava[ill]","ipa":"[tʁa.vaj]","ru":"работа"},{"w":"feu[ill]e","ipa":"[fœj]","ru":"лист"}]},{"c":"Согласные","l":"ill (исключения)","ipa":"[il]","ru":"«иль»","d":"В нескольких словах читается «иль».","ex":[{"w":"v[ill]e","ipa":"[vil]","ru":"город"},{"w":"m[ill]e","ipa":"[mil]","ru":"тысяча"},{"w":"tranqu[ill]e","ipa":"[tʁɑ̃.kil]","ru":"спокойный"}]},{"c":"Согласные","l":"c","ipa":"[s] / [k]","ru":"«с» / «к»","d":"Перед e, i, y — «с», иначе — «к».","ex":[{"w":"[c]inéma","ipa":"[si.ne.ma]","ru":"кино"},{"w":"[c]afé","ipa":"[ka.fe]","ru":"кофе"},{"w":"[c]itron","ipa":"[si.tʁɔ̃]","ru":"лимон"}]},{"c":"Согласные","l":"ç","ipa":"[s]","ru":"«с»","d":"Седиль превращает c в «с» перед a, o, u.","ex":[{"w":"fran[ç]ais","ipa":"[fʁɑ̃.sɛ]","ru":"французский"},{"w":"gar[ç]on","ipa":"[ɡaʁ.sɔ̃]","ru":"мальчик"},{"w":"le[ç]on","ipa":"[lə.sɔ̃]","ru":"урок"}]},{"c":"Согласные","l":"g","ipa":"[ʒ] / [g]","ru":"«ж» / «г»","d":"Перед e, i, y — «ж», иначе — «г».","ex":[{"w":"[g]are","ipa":"[ɡaʁ]","ru":"вокзал"},{"w":"rou[g]e","ipa":"[ʁuʒ]","ru":"красный"},{"w":"[g]ilet","ipa":"[ʒi.lɛ]","ru":"жилет"}]},{"c":"Согласные","l":"j","ipa":"[ʒ]","ru":"«ж»","d":"Всегда мягкое «ж».","ex":[{"w":"[j]our","ipa":"[ʒuʁ]","ru":"день"},{"w":"[j]aune","ipa":"[ʒon]","ru":"жёлтый"},{"w":"[j]e","ipa":"[ʒə]","ru":"я"}]},{"c":"Согласные","l":"h","ipa":"—","ru":"не читается","d":"Буква h никогда не произносится.","ex":[{"w":"[h]omme","ipa":"[ɔm]","ru":"мужчина"},{"w":"[h]ôtel","ipa":"[o.tɛl]","ru":"гостиница"},{"w":"[h]iver","ipa":"[i.vɛʁ]","ru":"зима"}]},{"c":"Согласные","l":"qu","ipa":"[k]","ru":"«к»","d":"Буква u после q не читается.","ex":[{"w":"[qu]i","ipa":"[ki]","ru":"кто"},{"w":"[qu]atre","ipa":"[katʁ]","ru":"четыре"},{"w":"[qu]estion","ipa":"[kɛs.tjɔ̃]","ru":"вопрос"}]},{"c":"Согласные","l":"ph, th","ipa":"[f], [t]","ru":"«ф», «т»","d":"h после p и t не меняет звук.","ex":[{"w":"[ph]oto","ipa":"[fo.to]","ru":"фото"},{"w":"[th]é","ipa":"[te]","ru":"чай"},{"w":"pharmacie","ipa":"[faʁ.ma.si]","ru":"аптека"}]},{"c":"Согласные","l":"r","ipa":"[ʁ]","ru":"картавое «р»","d":"Произносится горлом, как при полоскании, язык лежит внизу.","ex":[{"w":"[r]ue","ipa":"[ʁy]","ru":"улица"},{"w":"pa[r]is","ipa":"[pa.ʁi]","ru":"Париж"},{"w":"t[r]ain","ipa":"[tʁɛ̃]","ru":"поезд"}]},{"c":"Согласные","l":"s между гласными","ipa":"[z]","ru":"«з»","d":"Одна s между гласными звучит как «з», двойная ss — как «с».","ex":[{"w":"mai[s]on","ipa":"[mɛ.zɔ̃]","ru":"дом"},{"w":"poi[ss]on","ipa":"[pwa.sɔ̃]","ru":"рыба"},{"w":"poi[s]on","ipa":"[pwa.zɔ̃]","ru":"яд"}]},{"c":"Окончания","l":"Немые согласные","ipa":"—","ru":"не читаются","d":"Конечные d, t, s, x, z, p обычно не произносятся. Читаются часто c, r, f, l (как в слове CaReFuL).","ex":[{"w":"peti[t]","ipa":"[pti]","ru":"маленький"},{"w":"gran[d]","ipa":"[ɡʁɑ̃]","ru":"большой"},{"w":"pari[s]","ipa":"[pa.ʁi]","ru":"Париж"},{"w":"sa[c]","ipa":"[sak]","ru":"сумка"}]},{"c":"Окончания","l":"-er, -ez, -et","ipa":"[e]","ru":"«е»","d":"Окончания глаголов -er и -ez звучат как é.","ex":[{"w":"parl[er]","ipa":"[paʁ.le]","ru":"говорить"},{"w":"vous parl[ez]","ipa":"[vu paʁ.le]","ru":"вы говорите"},{"w":"n[ez]","ipa":"[ne]","ru":"нос"}]},{"c":"Окончания","l":"-ent у глаголов","ipa":"—","ru":"не читается","d":"В форме «ils/elles» окончание -ent немое.","ex":[{"w":"ils parl[ent]","ipa":"[il paʁl]","ru":"они говорят"},{"w":"elles mang[ent]","ipa":"[ɛl mɑ̃ʒ]","ru":"они едят"}]},{"c":"Окончания","l":"-e на конце","ipa":"—","ru":"не читается","d":"Но оно делает предыдущую согласную слышимой.","ex":[{"w":"peti[te]","ipa":"[pə.tit]","ru":"маленькая"},{"w":"gran[de]","ipa":"[ɡʁɑ̃d]","ru":"большая"},{"w":"ver[te]","ipa":"[vɛʁt]","ru":"зелёная"}]},{"c":"Окончания","l":"-tion","ipa":"[sjɔ̃]","ru":"«сьон»","d":"t перед -ion читается как «с».","ex":[{"w":"na[tion]","ipa":"[na.sjɔ̃]","ru":"нация"},{"w":"sta[tion]","ipa":"[sta.sjɔ̃]","ru":"станция"},{"w":"ques[tion]","ipa":"[kɛs.tjɔ̃]","ru":"вопрос (исключение: «тьон»)"}]},{"c":"Связывание","l":"Liaison","ipa":"—","ru":"связывание","d":"Немая конечная согласная звучит, если следующее слово начинается с гласной: s и x звучат как «з».","ex":[{"w":"les[_]amis","ipa":"[le.za.mi]","ru":"друзья"},{"w":"vous[_]avez","ipa":"[vu.za.ve]","ru":"у вас есть"},{"w":"un[_]enfant","ipa":"[œ̃.nɑ̃.fɑ̃]","ru":"ребёнок"}]},{"c":"Связывание","l":"Enchaînement","ipa":"—","ru":"сцепление","d":"Произносимая конечная согласная переходит к следующему слову.","ex":[{"w":"elle[_]a","ipa":"[ɛ.la]","ru":"у неё есть"},{"w":"il[_]arrive","ipa":"[i.la.ʁiv]","ru":"он приходит"},{"w":"avec[_]elle","ipa":"[a.vɛ.kɛl]","ru":"с ней"}]},{"c":"Связывание","l":"Élision","ipa":"—","ru":"выпадение гласной","d":"le, la, je, ne, de, que теряют гласную перед гласной: появляется апостроф.","ex":[{"w":"[l’]eau","ipa":"[lo]","ru":"вода"},{"w":"[j’]aime","ipa":"[ʒɛm]","ru":"я люблю"},{"w":"[c’]est","ipa":"[sɛ]","ru":"это"}]}];
